import collections

class RestAPI:
    def __init__(self, database=None):
        """
        Initializes the RestAPI with an optional database.
        The database, if provided, should be a dictionary where keys are user names
        and values are dictionaries containing "name", "owes", and "owed_by" fields.
        """
        self.users_data = {}

        if database:
            for user_name, user_info in database.items():
                self.users_data[user_name] = {
                    "name": user_name,
                    "owes": user_info.get("owes", {}).copy(),
                    "owed_by": user_info.get("owed_by", {}).copy()
                }

    def _get_user_representation(self, user_name):
        """
        Helper method to construct a user object in the format specified by the API.
        Calculates the balance and filters out zero amounts for 'owes' and 'owed_by'.
        """
        user_obj = self.users_data.get(user_name)
        if not user_obj:
            return None

        # Calculate balance: (total owed by other users) - (total owed to other users)
        total_owed_by = sum(user_obj["owed_by"].values())
        total_owes = sum(user_obj["owes"].values())
        balance = total_owed_by - total_owes

        # Filter out zero amounts for a cleaner output, as per example
        owes_filtered = {k: v for k, v in user_obj["owes"].items() if v > 0}
        owed_by_filtered = {k: v for k, v in user_obj["owed_by"].items() if v > 0}

        return {
            "name": user_obj["name"],
            "owes": owes_filtered,
            "owed_by": owed_by_filtered,
            "balance": balance
        }

    def get(self, url, payload=None):
        """
        Handles GET requests to the API.
        Currently supports '/users' URL.
        """
        if url == "/users":
            if payload is None or not payload.get("users"):
                # If no specific users are requested, return information for all users, sorted by name.
                all_user_names = sorted(self.users_data.keys())
                result_users = [self._get_user_representation(name) for name in all_user_names]
                return {"users": result_users}
            else:
                # Return information for specified users, sorted by name.
                requested_user_names = sorted(payload["users"])
                result_users = []
                for user_name in requested_user_names:
                    if user_name in self.users_data:
                        result_users.append(self._get_user_representation(user_name))
                return {"users": result_users}

        # For unsupported URLs, return None or raise an appropriate error.
        return None

    def post(self, url, payload=None):
        """
        Handles POST requests to the API.
        Currently supports '/add' and '/iou' URLs.
        """
        if url == "/add":
            if not payload or "user" not in payload:
                raise ValueError("Payload must contain 'user' field.")

            new_user_name = payload["user"]

            if not isinstance(new_user_name, str) or not new_user_name:
                raise ValueError("User name must be a non-empty string.")

            if new_user_name in self.users_data:
                raise ValueError(f"User '{new_user_name}' already exists.")

            self.users_data[new_user_name] = {
                "name": new_user_name,
                "owes": {},
                "owed_by": {}
            }
            return self._get_user_representation(new_user_name)

        elif url == "/iou":
            if not payload:
                raise ValueError("Payload cannot be empty for /iou.")

            lender_name = payload.get("lender")
            borrower_name = payload.get("borrower")
            amount = payload.get("amount")

            # Validate input payload
            if not all([lender_name, borrower_name, amount is not None]):
                raise ValueError("Payload must contain 'lender', 'borrower', and 'amount'.")

            if not isinstance(lender_name, str) or not isinstance(borrower_name, str) \
                or not lender_name or not borrower_name:
                raise ValueError("Lender and borrower names must be non-empty strings.")

            if not isinstance(amount, (int, float)) or amount <= 0:
                raise ValueError("Amount must be a positive number.")

            if lender_name == borrower_name:
                raise ValueError("Lender and borrower cannot be the same person.")

            if lender_name not in self.users_data:
                raise ValueError(f"Lender '{lender_name}' does not exist.")
            if borrower_name not in self.users_data:
                raise ValueError(f"Borrower '{borrower_name}' does not exist.")

            lender_obj = self.users_data[lender_name]
            borrower_obj = self.users_data[borrower_name]

            # Update borrower's 'owes' to the lender
            borrower_obj["owes"][lender_name] = borrower_obj["owes"].get(lender_name, 0.0) + amount
            # Update lender's 'owed_by' from the borrower
            lender_obj["owed_by"][borrower_name] = lender_obj["owed_by"].get(borrower_name, 0.0) + amount

            # Prepare response: updated User objects for lender and borrower, sorted by name
            updated_users = [
                self._get_user_representation(lender_name),
                self._get_user_representation(borrower_name)
            ]
            updated_users.sort(key=lambda u: u["name"])
            return {"users": updated_users}

        # For unsupported URLs, return None or raise an appropriate error.
        return None
